                _focus={{ boxShadow: `0 0 0 3px ${colors.accentSoft}`, borderColor: colors.primary }}
            />
            {error ? <Field.ErrorText>{error}</Field.ErrorText> : null}
        </Field.Root>
    );
};

export default TextField;
